int get(int n)
{
    int curr = 1;
    int start = 1;
    if (n >= p)
    {
        int idx = ((n - p) / p);
        for (int i = 0; i <= idx; i++)
        {
            curr *= calc[i];
            curr %= mod;
        }
        start = idx * p + p + 1;
    }
    for (int i = start; i <= n; i++)
    {
        curr *= i;
        curr %= mod;
    }
    return curr;
}
